CREATE TABLE `flight_bookings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `provider_id` tinyint(3) unsigned NOT NULL,
  `booking_reference` varchar(30) NOT NULL,
  `provider_order_id` varchar(100) DEFAULT NULL,
  `provider_offer_id` varchar(100) DEFAULT NULL COMMENT 'Duffel offer_id used to create this order',
  `duffel_booking_reference` varchar(30) DEFAULT NULL COMMENT 'Airline PNR from Duffel order.booking_reference',
  `pending_cancellation_id` varchar(100) DEFAULT NULL,
  `trip_type` enum('one_way','round_trip','multi_city') NOT NULL,
  `cabin_class` enum('economy','premium_economy','business','first') NOT NULL DEFAULT 'economy',
  `adults_count` tinyint(4) NOT NULL DEFAULT 1,
  `children_count` tinyint(4) NOT NULL DEFAULT 0,
  `infants_count` tinyint(4) NOT NULL DEFAULT 0,
  `origin_airport` char(3) NOT NULL,
  `destination_airport` char(3) NOT NULL,
  `departure_at` datetime NOT NULL,
  `return_at` datetime DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `currency` char(3) NOT NULL DEFAULT 'GBP',
  `status` enum('pending','confirmed','cancelled','changed','awaiting_payment','failed') NOT NULL DEFAULT 'pending' COMMENT 'Booking lifecycle status',
  `cancellation_reason` text DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  `cancellation_refund_amount` decimal(12,2) DEFAULT NULL,
  `paid_at` datetime DEFAULT NULL COMMENT 'payment_status.paid_at from Duffel',
  `payment_required_by` datetime DEFAULT NULL COMMENT 'payment_status.payment_required_by — booking expires',
  `price_guarantee_expires_at` datetime DEFAULT NULL COMMENT 'payment_status.price_guarantee_expires_at',
  `void_window_ends_at` datetime DEFAULT NULL COMMENT 'order.void_window_ends_at — free-cancel deadline',
  `available_actions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'order.available_actions array' CHECK (json_valid(`available_actions`)),
  `synced_at` datetime DEFAULT NULL COMMENT 'Last Duffel getOrder() refresh timestamp',
  `live_mode` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'order.live_mode (0=test, 1=live)',
  `cancellation_refund_to` varchar(60) DEFAULT NULL COMMENT 'cancellation.refund_to field from Duffel',
  `cancellation_expires_at` datetime DEFAULT NULL COMMENT 'cancellation.expires_at — quote validity deadline',
  `refund_conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'conditions.refund_before_departure from order/offer' CHECK (json_valid(`refund_conditions`)),
  `change_conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'conditions.change_before_departure from order/offer' CHECK (json_valid(`change_conditions`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `awaiting_payment` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Set when Duffel flags order.payment_status.awaiting_payment',
  `duffel_payment_failure` varchar(500) DEFAULT NULL COMMENT 'Duffel failure_reason or order creation error',
  `cancellation_refund_currency` char(3) DEFAULT NULL COMMENT 'Currency of Duffel refund_amount (may differ from charge currency)',
  `auto_refunded_at` datetime DEFAULT NULL COMMENT 'Timestamp of automatic Stripe refund on Duffel order failure',
  `booking_references` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'order.booking_references[] from Duffel — per-airline PNR array' CHECK (json_valid(`booking_references`)),
  `cancellation_confirmed_at` datetime DEFAULT NULL COMMENT 'Duffel order_cancellation.confirmed_at — when the cancellation was confirmed by airline',
  `change_fee_paid` decimal(10,2) DEFAULT NULL COMMENT 'Total change fees paid by customer (cumulative)',
  `refund_preference` enum('wallet','original_payment') DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_booking_ref` (`booking_reference`),
  KEY `idx_user_status` (`user_id`,`status`),
  KEY `idx_provider` (`provider_id`),
  KEY `idx_payment_deadline` (`payment_required_by`),
  KEY `idx_duffel_booking_ref` (`duffel_booking_reference`),
  KEY `idx_provider_offer` (`provider_offer_id`),
  CONSTRAINT `flight_bookings_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `flight_bookings_ibfk_2` FOREIGN KEY (`provider_id`) REFERENCES `providers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
;

CREATE TABLE `flight_booking_documents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `booking_id` int(10) unsigned NOT NULL,
  `document_type` varchar(50) NOT NULL COMMENT 'electronic_ticket | boarding_pass | itinerary',
  `unique_identifier` varchar(50) NOT NULL COMMENT 'Ticket number / document unique ID from Duffel',
  `passenger_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Array of Duffel passenger IDs this document covers' CHECK (json_valid(`passenger_ids`)),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_booking_doc` (`booking_id`,`unique_identifier`),
  KEY `idx_booking` (`booking_id`),
  CONSTRAINT `flight_booking_documents_ibfk_1` FOREIGN KEY (`booking_id`) REFERENCES `flight_bookings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
;

