  PRIMARY KEY (`id`),
  KEY `idx_booking` (`booking_id`),
  KEY `traveler_id` (`traveler_id`),
  CONSTRAINT `flight_booking_passengers_ibfk_1` FOREIGN KEY (`booking_id`) REFERENCES `flight_bookings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `flight_booking_passengers_ibfk_2` FOREIGN KEY (`traveler_id`) REFERENCES `travelers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
;

