  PRIMARY KEY (`id`),
  KEY `idx_booking` (`booking_id`),
  KEY `idx_booking_slice` (`booking_id`,`slice_index`),
  KEY `idx_airline` (`airline_code`),
  CONSTRAINT `flight_booking_segments_ibfk_1` FOREIGN KEY (`booking_id`) REFERENCES `flight_bookings` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci
;

CREATE TABLE `flight_booking_services` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
